import sys
from itertools import combinations

def can_form_tournament(scores):
    scores.sort()
    n = len(scores)
    total_sum = sum(scores)
    if total_sum != n * (n - 1) // 2:
        return False
    for k in range(1, n):
        if sum(scores[:k]) < k * (k - 1) // 2 + sum([min(n - 1 - x, k) for x in scores[:k]]):
            return False
    return True

def find_min_tournament(scores):
    scores.sort()
    n = len(scores)
    while True:
        if can_form_tournament(scores + [n - 1 - x for x in scores]):
            return n
        n += 1

def construct_tournament(n, scores):
    scores.sort()
    adj_matrix = [[0] * n for _ in range(n)]
    used_scores = [0] * n
    for i in range(n):
        remaining = scores[i]
        for j in range(n):
            if i != j and used_scores[j] < scores[j]:
                if remaining > 0:
                    adj_matrix[i][j] = 1
                    remaining -= 1
                    used_scores[j] += 1
    return adj_matrix

def main():
    import sys
    input = sys.stdin.read().split()
    m = int(input[0])
    scores = list(map(int, input[1:m+1]))

    if not can_form_tournament(scores):
        print("=(")
        return

    n = find_min_tournament(scores)
    adj_matrix = construct_tournament(n, scores)

    print(n)
    for row in adj_matrix:
        print(''.join(map(str, row)))

if __name__ == "__main__":
    main()
